-- Parity test for Cognos report Monthly_Invoice_Detail (cluster BIL_002, 1 runs/day)
-- Generated by SemanticLift 1.0.0; tolerance +/-0.5% on totals
WITH cognos AS (
    SELECT dt.FULL_DATE AS full_date, meter.METER_ID AS meter_id, meter.IS_SMART_METER AS is_smart_meter, tariff.TARIFF_TYPE AS tariff_type, customer.CUSTOMER_ID AS customer_id, customer.CUSTOMER_NAME AS customer_name, SUM(meter_reading.CONSUMPTION_KWH) AS total_consumption_kwh
    FROM CORE.FCT_METER_READING meter_reading
    JOIN CORE.DIM_DATE dt ON meter_reading.DATE_KEY = dt.DATE_KEY
    JOIN CORE.DIM_METER meter ON meter_reading.METER_ID = meter.METER_ID
    JOIN CORE.DIM_TARIFF tariff ON meter_reading.TARIFF_ID = tariff.TARIFF_ID
    JOIN CORE.DIM_CUSTOMER customer ON meter.CUSTOMER_ID = customer.CUSTOMER_ID
    WHERE dt.FISCAL_YEAR = 2026
    GROUP BY 1, 2, 3, 4, 5, 6
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_METER_CONSUMPTION
        DIMENSIONS dt.full_date, meter.meter_id, meter.is_smart_meter, tariff.tariff_type, customer.customer_id, customer.customer_name
        METRICS meter_reading.total_consumption_kwh
    ) WHERE fiscal_year = 2026
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.total_consumption_kwh) AS cognos_total_consumption_kwh, SUM(s.total_consumption_kwh) AS semantic_total_consumption_kwh,
    IFF(ABS(COALESCE(SUM(s.total_consumption_kwh), 0) - COALESCE(SUM(c.total_consumption_kwh), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_consumption_kwh), 0)), 'PASS', 'FAIL') AS status_total_consumption_kwh
FROM cognos c
FULL OUTER JOIN semantic s ON c.full_date IS NOT DISTINCT FROM s.full_date AND c.meter_id IS NOT DISTINCT FROM s.meter_id AND c.is_smart_meter IS NOT DISTINCT FROM s.is_smart_meter AND c.tariff_type IS NOT DISTINCT FROM s.tariff_type AND c.customer_id IS NOT DISTINCT FROM s.customer_id AND c.customer_name IS NOT DISTINCT FROM s.customer_name;
